/// What one envelope from the mailbox did.
class InboxEvent {
  /// Send this frame back over the WebSocket; `None` leaves the envelope
  /// for a later attempt.
  final Uint8List? ack;

  /// The chat that changed, if any.
  final String? chat;

  /// Someone started a chat with this device.
  final bool joined;

  /// A change took this device out of the chat; it may have been
  /// removed from its account.
  final bool left;

  /// Why the envelope was refused, if it was.
  final String? refused;

  /// A new message from someone else, worth a notification.
  final Notice? notice;

  /// What a call message asks of this device (ADR-0019).
  final CallSignal? call;

  const InboxEvent({
    this.ack,
    this.chat,
    required this.joined,
    required this.left,
    this.refused,
    this.notice,
    this.call,
  });

  @override
  int get hashCode =>
      ack.hashCode ^
      chat.hashCode ^
      joined.hashCode ^
      left.hashCode ^
      refused.hashCode ^
      notice.hashCode ^
      call.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is InboxEvent &&
          runtimeType == other.runtimeType &&
          ack == other.ack &&
          chat == other.chat &&
          joined == other.joined &&
          left == other.left &&
          refused == other.refused &&
          notice == other.notice &&
          call == other.call;
}

