/// Where an outgoing message is.
enum MessageStatus {
  /// Waiting to go out (offline, or not yet acknowledged by the service).
  queued,

  /// The service has it.
  sent,

  /// On someone else's device.
  delivered,

  /// Read by someone else.
  read,
}

/// One message as the chat screen shows it.
class MessageView {
  /// Message id, base64url.
  final String id;

  /// Position in this device's history; pass the smallest one to load
  /// older messages.
  final PlatformInt64 seq;
  final bool outgoing;

  /// The text, or a placeholder for what cannot be shown.
  final String text;

  /// Deleted by its author; `text` is empty.
  final bool deleted;

  /// A kind this version cannot show; the app asks to update.
  final bool unsupported;
  final bool edited;

  /// Author's clock, UTC milliseconds: what the app displays.
  final PlatformInt64 sentAtMs;

  /// Meaningful for outgoing messages only.
  final MessageStatus status;

  /// The message this one answers.
  final Quote? replyTo;

  /// Reactions, most chosen first.
  final List<Reaction> reactions;

  /// The user's own text, still there: it can be edited and deleted.
  final bool editable;

  /// Who wrote it: `@bob`, or a short fingerprint for an unknown account.
  final String author;

  /// A photo, a document or a voice message.
  final FileView? file;

  /// Something that happened to the chat, shown as a line rather than a
  /// bubble; `text` is empty then.
  final ChatEvent? event;

  /// A call; `text` is empty then.
  final CallView? call;

  const MessageView({
    required this.id,
    required this.seq,
    required this.outgoing,
    required this.text,
    required this.deleted,
    required this.unsupported,
    required this.edited,
    required this.sentAtMs,
    required this.status,
    this.replyTo,
    required this.reactions,
    required this.editable,
    required this.author,
    this.file,
    this.event,
    this.call,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      seq.hashCode ^
      outgoing.hashCode ^
      text.hashCode ^
      deleted.hashCode ^
      unsupported.hashCode ^
      edited.hashCode ^
      sentAtMs.hashCode ^
      status.hashCode ^
      replyTo.hashCode ^
      reactions.hashCode ^
      editable.hashCode ^
      author.hashCode ^
      file.hashCode ^
      event.hashCode ^
      call.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MessageView &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          seq == other.seq &&
          outgoing == other.outgoing &&
          text == other.text &&
          deleted == other.deleted &&
          unsupported == other.unsupported &&
          edited == other.edited &&
          sentAtMs == other.sentAtMs &&
          status == other.status &&
          replyTo == other.replyTo &&
          reactions == other.reactions &&
          editable == other.editable &&
          author == other.author &&
          file == other.file &&
          event == other.event &&
          call == other.call;
}

